// Option specs
type optSpec struct {
	short string // single char, e.g., "a", or "" if none? All have short.
	long  string // e.g., "attribute"
	takesValue bool
	multiple bool // only r allows multiple
	placeholder string // for USAGE/error, e.g., "<attribute>", "<FILE>", "<SELECTOR>...", "" for flags
}

var specs = map[string]*optSpec{ // key by long
	"detect-base":       {short: "B", long: "detect-base", takesValue: false, multiple: false, placeholder: ""},
	"help":              {short: "h", long: "help", takesValue: false, multiple: false, placeholder: ""},
	"ignore-whitespace": {short: "w", long: "ignore-whitespace", takesValue: false, multiple: false, placeholder: ""},
	"pretty":            {short: "p", long: "pretty", takesValue: false, multiple: false, placeholder: ""},
	"text":              {short: "t", long: "text", takesValue: false, multiple: false, placeholder: ""},
	"version":           {short: "V", long: "version", takesValue: false, multiple: false, placeholder: ""},
	"attribute":         {short: "a", long: "attribute", takesValue: true, multiple: false, placeholder: "<attribute>"},
	"base":              {short: "b", long: "base", takesValue: true, multiple: false, placeholder: "<base>"},
	"filename":          {short: "f", long: "filename", takesValue: true, multiple: false, placeholder: "<FILE>"},
	"output":            {short: "o", long: "output", takesValue: true, multiple: false, placeholder: "<FILE>"},
	"remove-nodes":      {short: "r", long: "remove-nodes", takesValue: true, multiple: true, placeholder: "<SELECTOR>..."},
}

var shortToLong = map[string]string{
	"B": "detect-base",
	"h": "help",
	"w": "ignore-whitespace",
	"p": "pretty",
	"t": "text",
	"V": "version",
	"a": "attribute",
	"b": "base",
	"f": "filename",
	"o": "output",
	"r": "remove-nodes",
}

func binName() string {
	return filepath.Base(os.Args[0])
}

func helpText() string {
	bin := binName()
	return fmt.Sprintf(`htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    %s [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]
`, bin)
}

func versionText() string {
	return "htmlq 0.4.0\n"
}

// usageForFlags generates USAGE line for error with given longs (sorted)
func usageForFlags(longs []string) string {
	bin := binName()
	if len(longs) == 0 {
		return fmt.Sprintf("    %s [FLAGS] [OPTIONS] [--] [selector]...", bin)
	}
	// sort alphabetically by long
	sorted := append([]string{}, longs...)
	sort.Strings(sorted)
	parts := []string{bin}
	for _, l := range sorted {
		spec := specs[l]
		if spec.takesValue {
			parts = append(parts, fmt.Sprintf("--%s %s", l, spec.placeholder))
		} else {
			parts = append(parts, fmt.Sprintf("--%s", l))
		}
	}
	return "    " + strings.Join(parts, " ")
}

func printUnknownError(argName string, priorLongs []string) {
	// argName is like "'--unknown'" or "'-Z'" with quotes
	binUsage := ""
	if len(priorLongs) == 0 {
		binUsage = usageForFlags(nil)
	} else {
		// deduplicate priorLongs for USAGE? If prior has duplicates? For unknown, prior are collected before unknown, no duplicates yet? But could have duplicate? e.g., -t -t -Z: prior before -Z includes -t twice? Should USAGE include --text once? Original for -t -t -Z gave USAGE with --text once (not twice). Good. So dedup.
		uniq := map[string]bool{}
		var list []string
		for _, l := range priorLongs {
			if !uniq[l] {
				uniq[l] = true
				list = append(list, l)
			}
		}
		binUsage = usageForFlags(list)
	}
	fmt.Fprintf(os.Stderr, "error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n%s\n\nFor more information try --help\n", argName, binUsage)
}

func printMissingError(long string, allLongs []string) {
	spec := specs[long]
	// allLongs includes missing + others, deduped, sorted via usageForFlags
	uniq := map[string]bool{}
	var list []string
	for _, l := range allLongs {
		if !uniq[l] {
			uniq[l] = true
			list = append(list, l)
		}
	}
	// ensure missing included
	if !uniq[long] {
		list = append(list, long)
	}
	usage := usageForFlags(list)
	fmt.Fprintf(os.Stderr, "error: The argument '--%s %s' requires a value but none was supplied\n\nUSAGE:\n%s\n\nFor more information try --help\n", long, spec.placeholder, usage)
}

func printDuplicateError(long string, allLongs []string) {
	spec := specs[long]
	uniq := map[string]bool{}
	var list []string
	for _, l := range allLongs {
		if !uniq[l] {
			uniq[l] = true
			list = append(list, l)
		}
	}
	if !uniq[long] {
		list = append(list, long)
	}
	usage := usageForFlags(list)
	if spec.takesValue {
		fmt.Fprintf(os.Stderr, "error: The argument '--%s %s' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n%s\n\nFor more information try --help\n", long, spec.placeholder, usage)
	} else {
		fmt.Fprintf(os.Stderr, "error: The argument '--%s' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n%s\n\nFor more information try --help\n", long, usage)
	}
}

type parsedArgs struct {
	detectBase bool
	help bool
	ignoreWhitespace bool
	pretty bool
	text bool
	version bool
	attribute *string
	base *string
	filename *string
	output *string
	removeNodes []string
	selectors []string
}

func main() {
	// CLI parsing
	args := os.Args[1:]
	// Track counts for duplicate detection (excluding help/version? help/version don't count for duplicate? They short-circuit, no duplicate error)
	counts := map[string]int{}
	// Collect all longs for USAGE in missing/duplicate (including all supplied, even if missing?)
	// For missing/duplicate USAGE, need all supplied flags (including missing?).
	// We'll collect in order.
	var allLongsOrdered []string // in encounter order, for USAGE (will dedup+sort later)
	// Prior longs for unknown (only before unknown)
	var priorLongs []string

